function validate([logs]) {
  if (!Array.isArray(logs) || logs.length < 1 || logs.length > 100) return 'logs needs 1 to 100 people.';
  for (const entry of logs) {
    if (!Array.isArray(entry) || entry.length !== 2 || !entry.every(Number.isInteger)) return 'Each log is a pair [birth, death] of whole years.';
    const [birth, death] = entry;
    if (birth < 1950 || death > 2050) return 'Years must be between 1950 and 2050.';
    if (birth >= death) return 'Each birth year must come before the death year.';
  }
  return null;
}

