function maximumPopulation(logs) {
  const delta = new Array(101).fill(0);
  for (const [birth, death] of logs) {
    delta[birth - 1950]++;
    delta[death - 1950]--;
  }

  let alive = 0;
  let best = 0;
  let bestYear = 1950;
  for (let offset = 0; offset < 101; offset++) {
    alive += delta[offset];
    if (alive > best) {
      best = alive;
      bestYear = 1950 + offset;
    }
  }
  return bestYear;
}

