function maximumPopulation(logs) {
  let answer = -1;
  let most = -1;
  for (let year = 1950; year <= 2050; year++) {
    const count = logs.filter(([birth, death]) => birth <= year && year < death).length;
    if (count > most) {
      most = count;
      answer = year;
    }
  }
  return answer;
}

