function generate(rand, size) {
  const count = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 6);
  const narrow = size === 'small' && rand() < 0.5;
  const low = narrow ? 1950 + Math.floor(rand() * 90) : 1950;
  const high = narrow ? Math.min(2050, low + 10) : 2050;
  const logs = [];
  for (let k = 0; k < count; k++) {
    const birth = low + Math.floor(rand() * (high - low));
    const death = birth + 1 + Math.floor(rand() * (high - birth));
    logs.push([birth, death]);
  }
  return [logs];
}
